<script setup lang="ts">import { inject, type Ref } from "vue"; import { downloadRepairReceipt, type Repair } from "../../api"; const repair = inject<Ref<Repair | null>>("repair"); async function downloadReceipt(): Promise<void> { if (!repair?.value) return; const url = URL.createObjectURL(await downloadRepairReceipt(repair.value.id)); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `resguardo-${repair.value.id.slice(0, 8)}.pdf`; anchor.click(); URL.revokeObjectURL(url); }</script><template><section v-if="repair" class="detail-tab"><header><h2>Equipo y recepcion</h2><button class="secondary" type="button" @click="downloadReceipt">Descargar resguardo</button></header><dl><dt>Tipo</dt><dd>{{ repair.deviceType }}</dd><dt>Serie</dt><dd>{{ repair.serialNumber || "No indicada" }}</dd><dt>Averia</dt><dd>{{ repair.reportedIssue }}</dd><dt>Accesorios</dt><dd>{{ repair.deliveredAccessories || "No indicados" }}</dd></dl></section></template>